fun overtimeThreshold(settings: AppSettings): Double = when(settings.overtimeMode) {
    "WEEKLY" -> settings.weeklyRegularHours
    "MONTHLY" -> settings.monthlyRegularHours
    else -> settings.regularHours
}

/** Retain the app's assigned-work-date convention, including overnight/imported records. */
fun overtimeBucketStart(date: LocalDate,settings: AppSettings): LocalDate = when(settings.overtimeMode) {
    "WEEKLY" -> date.minusDays(Math.floorMod(date.dayOfWeek.value-settings.weekStartDay,7).toLong())
    "MONTHLY" -> if(settings.overtimeMonthBasis=="CALENDAR")date.withDayOfMonth(1) else periodFor(date,settings.periodStartDay).from
    else -> date
}

fun overtimeModeLabel(mode: String): String = tr(when(mode) {
