    "MONTHLY" -> R.string.ot_monthly
    else -> R.string.ot_daily
})

fun overtimeRuleDescription(s: AppSettings): String = overtimeModeLabel(s.overtimeMode)+" · "+number(overtimeThreshold(s))+" "+tr(R.string.ot_hours)+when(s.overtimeMode) {
    "WEEKLY" -> " · "+tr(R.string.ot_week_start)+": "+DayOfWeek.of(s.weekStartDay).getDisplayName(TextStyle.FULL,appLocale)
    "MONTHLY" -> " · "+tr(if(s.overtimeMonthBasis=="CALENDAR")R.string.ot_calendar else R.string.ot_pay_period)
    else -> ""
