/** Office-only comparison uses actual net durations AFTER shared break allocation. */
fun officeOnlyOvertime(days: List<DayTotal>,s: AppSettings,period: PayPeriod): Double {
    val used=mutableMapOf<LocalDate,Double>()
    var result=0.0
    days.sortedBy {it.day}.forEach { day ->
        val key=overtimeBucketStart(day.day,s)
        day.parts.filter {it.shift.location==OFFICE}.sortedBy {it.shift.start}.forEach { part ->
            val before=used[key] ?: 0.0
            val after=before+part.netMs
            if(period.contains(day.day)) result+=(after-overtimeThreshold(s)*HOUR_MS).coerceAtLeast(0.0)-(before-overtimeThreshold(s)*HOUR_MS).coerceAtLeast(0.0)
            used[key]=after
        }
    }
    return result
}
